CREATE TABLE user_account(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,display_name VARCHAR(100) NOT NULL,password_hash VARCHAR(200) NOT NULL,role_code VARCHAR(30) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT ck_user_role CHECK(role_code IN('GUARD','DORM_ADMIN','ADMIN','SYSTEM_ADMIN')));
